"""Writes the Renguin badge (an HVIF icon) as a C header for linux-apps,
which draws it onto the icons of Linux programs (roadmap F-27, "A Renguin
badge"):

    3rdparty/ce/tools/make_renguin_badge_icon.py > \\
        src/bin/linux/RenguinBadge.h
    3rdparty/ce/tools/make_renguin_badge_icon.py --rdef  (linux-apps.rdef's
        vector_icon)
    3rdparty/ce/tools/make_renguin_badge_icon.py --preview badge.png

The picture: a Renga-green leaf, tilted, with a small penguin silhouette
(dark back, light front, orange beak and feet) standing on it. Vector, so
it stays sharp at any icon size (HiDPI). No mascot artwork is copied: the
penguin is a plain geometric figure.
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import hvif

GREEN = ((132, 196, 78, 255), (70, 132, 40, 255))
VEIN = (52, 98, 30, 255)
DARK = ((60, 62, 70, 255), (18, 18, 24, 255))
LIGHT = ((252, 252, 248, 255), (214, 214, 206, 255))
ORANGE = ((248, 170, 50, 255), (214, 110, 24, 255))
OUTLINE = (24, 40, 18, 255)


def ellipse(cx, cy, rx, ry, steps=20):
	import math
	return [(cx + rx * math.cos(2 * math.pi * i / steps),
		cy + ry * math.sin(2 * math.pi * i / steps)) for i in range(steps)]


def leaf():
	# a pointed leaf from the lower left to the upper right
	import math
	points = []
	for i in range(13):
		t = i / 12.0
		x = 6 + 52 * t
		y = 58 - 52 * t
		bulge = math.sin(math.pi * t) * 15
		points.append((x - bulge * 0.7, y - bulge * 0.7))
	for i in range(11, 0, -1):
		t = i / 12.0
		x = 6 + 52 * t
		y = 58 - 52 * t
		bulge = math.sin(math.pi * t) * 15
		points.append((x + bulge * 0.7, y + bulge * 0.7))
	return points


def build():
	icon = hvif.Icon()
	icon.polygon(leaf(), hvif.gradient((6, 58), (58, 6),
		[(0, GREEN[0]), (255, GREEN[1])]), outline=(OUTLINE, 3))
	# the vein
	icon.polygon([(9, 56), (52, 13), (53, 14), (10, 57)], VEIN)
	# the penguin: body, front, head, beak, feet
	icon.polygon(ellipse(34, 34, 11, 15), hvif.gradient((24, 20), (44, 48),
		[(0, DARK[0]), (255, DARK[1])]))
	icon.polygon(ellipse(36, 37, 7, 11), hvif.gradient((30, 28), (42, 48),
		[(0, LIGHT[0]), (255, LIGHT[1])]))
	icon.polygon([(39, 23), (46, 25), (39, 27)], hvif.gradient((39, 23),
		(46, 27), [(0, ORANGE[0]), (255, ORANGE[1])]))
	icon.polygon(ellipse(37, 24, 1.6, 1.6, 8), LIGHT[0])
	icon.polygon(ellipse(30, 49, 4, 2, 10), hvif.gradient((26, 47), (34, 51),
		[(0, ORANGE[0]), (255, ORANGE[1])]))
	icon.polygon(ellipse(39, 49, 4, 2, 10), hvif.gradient((35, 47), (43, 51),
		[(0, ORANGE[0]), (255, ORANGE[1])]))
	return icon


def header():
	data = build().flat()
	lines = ["/*", " * Copyright 2026, Renga contributors.",
		" * Distributed under the terms of the MIT License.", " *",
		" * The Renguin badge (HVIF). Generated by",
		" * 3rdparty/ce/tools/make_renguin_badge_icon.py; see there.",
		" */", "#ifndef RENGUIN_BADGE_H", "#define RENGUIN_BADGE_H", "",
		"", "static const unsigned char kRenguinBadge[] = {"]
	for i in range(0, len(data), 12):
		lines.append("\t" + ", ".join("0x%02x" % b for b in data[i:i + 12])
			+ ",")
	lines.append("};")
	lines.append("")
	lines.append("")
	lines.append("#endif	// RENGUIN_BADGE_H")
	return "\n".join(lines) + "\n"


def rdef_icon():
	hexdata = build().flat().hex().upper()
	lines = ["resource vector_icon {"]
	for i in range(0, len(hexdata), 64):
		lines.append("\t$\"%s\"" % hexdata[i:i + 64])
	lines.append("};")
	return "\n".join(lines) + "\n"


if __name__ == "__main__":
	if len(sys.argv) == 2 and sys.argv[1] == "--rdef":
		# the vector_icon resource alone, for linux-apps.rdef
		print(rdef_icon(), end="")
	elif len(sys.argv) == 3 and sys.argv[1] == "--preview":
		from PIL import Image
		icon = build()
		sheet = Image.new("RGBA", (16 + 32 + 64 + 128 + 40, 140),
			(216, 216, 216, 255))
		x = 8
		for size in (16, 32, 64, 128):
			sheet.paste(icon.preview(size, (216, 216, 216, 255)), (x, 4))
			x += size + 8
		sheet.save(sys.argv[2])
	else:
		print(header(), end="")
